
DROP TABLE IF EXISTS `poitranslations`;
CREATE TABLE `poitranslations` (
  `TranslationId` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `PoiId` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `LanguageCode` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Title` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Description` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `AudioUrl` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`TranslationId`),
  KEY `IX_PoiTranslations_PoiId` (`PoiId`),
  CONSTRAINT `FK_PoiTranslations_Pois_PoiId` FOREIGN KEY (`PoiId`) REFERENCES `pois` (`Id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


