INSERT INTO `poitranslations` (`TranslationId`, `PoiId`, `LanguageCode`, `Title`, `Description`, `AudioUrl`) VALUES 
(UUID(), '6addf224c5656cda07dfc241', 'en', NULL, 'You are standing at Thien Mu Pagoda, the oldest and most sacred pagoda in the ancient capital. Perched on Ha Khe Hill, gracefully reflecting on the tranquil Perfume River, Thien Mu Pagoda was built by Lord Nguyen Hoang in 1601. The most prominent symbol of the pagoda is the seven-story octagonal Phuoc Duyen Tower, towering against the blue sky. Not only a masterpiece of Buddhist architecture, this site also preserves the bronze bell that echoes morning and evening, as well as the historic Austin car of Bodhisattva Thich Quang Duc. Thien Mu Pagoda is a peaceful sanctuary where you can find inner serenity amidst the poetic atmosphere of Hue.', ''),
(UUID(), '6addf224c5656cda07dfc241', 'ja', NULL, 'あなたは今、古都で最も古く、最も神聖な寺院であるティエンムー寺に立っています。穏やかなフオン川に優雅に姿を映すハケの丘の上に立つティエンムー寺は、1601年にグエン・ホアン（阮潢）によって建立されました。この寺院の最も際立ったシンボルは、青空にそびえ立つ7階建ての八角形のフオックズエン塔（福縁塔）です。ここは仏教建築の傑作であるだけでなく、朝夕に響き渡る銅鐘や、ティック・クアン・ドック（釈広徳）菩薩の歴史的なオースチン車が保存されています。ティエンムー寺は、フエの詩的な雰囲気の中で内なる平穏を見つけることができる、平和な聖域です。', ''),
(UUID(), '6addf224c5656cda07dfc241', 'ko', NULL, '여러분은 지금 고도에서 가장 오래되고 신성한 사원인 티엔무 파고다에 서 계십니다. 잔잔한 향강(Perfume River)이 우아하게 비치는 하케(Ha Khe) 언덕에 위치한 티엔무 파고다는 1601년 응우옌 호앙(Nguyen Hoang) 영주가 세웠습니다. 이 사원의 가장 두드러진 상징은 푸른 하늘을 향해 우뚝 솟은 7층 팔각형의 푸옥듀엔(Phuoc Duyen) 탑입니다. 이곳은 불교 건축의 걸작일 뿐만 아니라 아침저녁으로 울려 퍼지는 청동 종과 틱꽝득(Thich Quang Duc) 보살의 역사적인 오스틴 자동차가 보존되어 있는 곳이기도 합니다. 티엔무 파고다는 후에의 시적인 분위기 속에서 내면의 평온을 찾을 수 있는 평화로운 안식처입니다.', ''),
(UUID(), '6addf224c5656cda07dfc241', 'vi', NULL, 'Bạn đang dừng chân tại chùa Thiên Mụ, ngôi chùa cổ kính và linh thiêng bậc nhất đất cố đô. Tọa lạc trên đồi Hà Khê, duyên dáng soi bóng xuống dòng sông Hương êm đềm, chùa Thiên Mụ được chúa Nguyễn Hoàng xây dựng vào năm 1601. Biểu tượng nổi bật nhất của chùa là tháp Phước Duyên hình bát giác cao 7 tầng, sừng sững vươn lên bầu trời xanh. Không chỉ là một kiệt tác kiến trúc Phật giáo, nơi đây còn lưu giữ tiếng chuông đồng vang vọng sớm chiều, cùng chiếc xe ô tô lịch sử của Bồ Tát Thích Quảng Đức. Chùa Thiên Mụ là một chốn bình yên, nơi bạn có thể tìm thấy sự thanh tịnh trong tâm hồn giữa không gian thơ mộng của xứ Huế.', ''),
(UUID(), '6addf224c5656cda07dfc241', 'zh', NULL, '您现在驻足的是天姥寺，这是古都最古老且最神圣的寺庙。天姥寺坐落于河溪山上，优雅地倒影在宁静的香江中，由阮潢领主于1601年建造。寺庙最著名的标志是高七层的八角形福缘塔，巍然耸立在蓝天之下。这里不仅是佛教建筑的杰作，还保存着晨钟暮鼓的铜钟，以及释广德菩萨的历史座驾。天姥寺是一处宁静的圣地，您可以在顺化诗意的氛围中寻得内心的平静。', ''),
(UUID(), '6addf22dc5656cda07dfc242', 'en', NULL, 'Welcome to the Tomb of Tu Duc, also known as Khiem Lang. Resembling a beautiful watercolor painting, this mausoleum clearly reflects the romantic and refined poetic soul of Emperor Tu Duc. Unlike the austere grandeur of other tombs, Tu Duc''s Tomb is an elegant architectural complex that blends seamlessly with the surrounding nature. Here, you will find the tranquil Luu Khiem Lake, the lushly shaded Tinh Khiem Island, and winding corridors connecting palaces and pavilions. Originally built as a retreat and place of leisure for the emperor during his lifetime, Khiem Lang possesses a melancholic yet deeply captivating beauty, leaving a profound impression on its visitors.', ''),
(UUID(), '6addf22dc5656cda07dfc242', 'ja', NULL, 'トゥドゥック帝陵、別名キエムラン（謙陵）へようこそ。美しい水墨画のようなこの陵墓は、トゥドゥック帝のロマンチックで洗練された詩的な魂をはっきりと映し出しています。他の陵墓の厳格な壮大さとは異なり、トゥドゥック帝陵は周囲の自然と見事に調和した優雅な建築群です。ここには、穏やかなルーキエム湖（流謙湖）、木陰が茂るティンキエム島（浄謙島）、そして宮殿や楼閣を結ぶ曲がりくねった回廊があります。元々は皇帝の生前の保養所や憩いの場として建てられたキエムランは、物憂げでありながらも非常に魅力的な美しさを持ち、訪れる人々に深い感銘を与えます。', ''),
(UUID(), '6addf22dc5656cda07dfc242', 'ko', NULL, '뜨득 황릉, 일명 킴랑(Khiem Lang)에 오신 것을 환영합니다. 아름다운 수묵화와도 같은 이 능은 뜨득 황제의 낭만적이고 세련된 시적 영혼을 잘 보여줍니다. 다른 능들의 엄숙한 웅장함과는 달리, 뜨득 황릉은 주변 자연과 완벽하게 조화를 이루는 우아한 건축 단지입니다. 이곳에는 잔잔한 루우 킴(Luu Khiem) 호수, 나무 그늘이 우거진 띤 킴(Tinh Khiem) 섬, 그리고 궁전과 누각을 연결하는 구불구불한 회랑이 있습니다. 원래 황제가 생전에 휴식과 여가를 즐기기 위한 장소로 지어진 킴랑은 애잔하면서도 깊은 매력을 지니고 있어 방문객들에게 깊은 인상을 남깁니다.', ''),
(UUID(), '6addf22dc5656cda07dfc242', 'vi', NULL, 'Chào mừng đến với Lăng Tự Đức, hay còn gọi là Khiêm Lăng. Được ví như một bức tranh thủy mặc tuyệt đẹp, lăng tẩm này phản ánh rõ nét tâm hồn thi sĩ lãng mạn và tinh tế của vua Tự Đức. Khác với sự uy nghiêm của các lăng tẩm khác, lăng Tự Đức là một quần thể kiến trúc nhã nhặn, hòa quyện tuyệt đối với thiên nhiên xung quanh. Nơi đây có hồ Lưu Khiêm êm đềm, có đảo Tịnh Khiêm mướt mát bóng cây, và những dải hành lang quanh co nối liền các cung điện, lầu các. Ban đầu được xây dựng làm chốn nghỉ ngơi, tiêu dao của nhà vua lúc sinh thời, Khiêm Lăng mang một vẻ đẹp u buồn nhưng vô cùng quyến rũ, để lại ấn tượng sâu sắc trong lòng người thưởng ngoạn.', ''),
(UUID(), '6addf22dc5656cda07dfc242', 'zh', NULL, '欢迎来到嗣德陵，又称谦陵。这座陵墓犹如一幅美丽的中国水墨画，生动地反映了嗣德皇帝浪漫而精致的诗人灵魂。与其他陵墓的庄严肃穆不同，嗣德陵是一个优雅的建筑群，与周围的自然环境完美融合。这里有宁静的流谦湖，绿树成荫的净谦岛，以及连接宫殿和楼阁的蜿蜒走廊。谦陵最初是作为皇帝生前的休闲隐退之所而建，它带着一种淡淡的忧伤，却又极具魅力，给游览者留下了深刻的印象。', ''),
(UUID(), '6addf272c5656cda07dfc243', 'en', NULL, 'You are visiting the Tomb of Khai Dinh, or Ung Lang, the most unique and controversial architectural work among the Nguyen Dynasty mausoleums. Khai Dinh''s Tomb is a bold and harmonious blend of Eastern and Western, Asian and European architectural styles, reflecting the personality of an emperor who favored novelty. Despite being the smallest in area, it was the most time-consuming, labor-intensive, and expensive tomb to build. The most brilliant highlight lies within the Thien Dinh Palace, featuring exquisite porcelain and glass mosaics, intricate in every detail. Resembling a majestic castle on the slopes of Chau Chu Mountain, the Tomb of Khai Dinh stands as a testament to a distinctive period of cultural crossover in Vietnamese history.', ''),
(UUID(), '6addf272c5656cda07dfc243', 'ja', NULL, 'あなたは今、グエン朝の陵墓の中で最もユニークで物議を醸した建築物であるカイディン帝陵（応陵）を訪れています。カイディン帝陵は、東西、アジア、ヨーロッパの建築様式が大胆かつ調和して融合しており、目新しいものを好んだ皇帝の個性を反映しています。面積は最も小さいにもかかわらず、建設に最も時間、労力、費用がかかりました。最も輝かしい見どころはティエンディン宮（天定宮）の内部にあり、細部に至るまで精巧な磁器とガラスのモザイク浮き彫りが特徴です。チャウチュー山（周字山）の斜面にそびえ立つ荘厳な城のようなカイディン帝陵は、ベトナムの歴史における独特の文化交差の時代を証しするものです。', ''),
(UUID(), '6addf272c5656cda07dfc243', 'ko', NULL, '여러분은 응우옌 왕조의 능 중에서 가장 독특하고 논란이 많은 건축물인 카이딘 황릉(응랑)을 방문하고 계십니다. 카이딘 황릉은 동서양, 아시아와 유럽의 건축 양식이 대담하고 조화롭게 혼합되어 있으며, 새로운 것을 선호했던 황제의 개성을 반영합니다. 면적은 가장 작지만, 건축하는 데 가장 많은 시간과 노동력, 그리고 비용이 들었습니다. 가장 찬란한 하이라이트는 티엔딘(Thien Dinh) 궁전 내부에 있는데, 세세한 부분까지 정교한 도자기와 유리 모자이크 부조가 특징입니다. 쩌우쯔(Chau Chu) 산 중턱에 자리 잡은 장엄한 성과 같은 카이딘 황릉은 베트남 역사의 독특한 문화 교류 시대를 증명하는 건축물입니다.', ''),
(UUID(), '6addf272c5656cda07dfc243', 'vi', NULL, 'Bạn đang ghé thăm Lăng Khải Định, hay Ứng Lăng, công trình kiến trúc độc đáo và gây nhiều tranh cãi nhất trong hệ thống lăng tẩm triều Nguyễn. Lăng Khải Định là sự pha trộn táo bạo và hài hòa giữa các trường phái kiến trúc Đông - Tây, Âu - Á, phản ánh cá tính của vị vua thích cái mới lạ. Dù có diện tích nhỏ nhất, nhưng đây lại là lăng tẩm tốn nhiều thời gian, công sức và tiền của nhất. Điểm nhấn rực rỡ nhất nằm ở Cung Thiên Định, với những bức phù điêu ghép bằng sành sứ và thủy tinh tinh xảo đến từng chi tiết. Lăng Khải Định như một tòa lâu đài uy nghi trên sườn núi Châu Chữ, là minh chứng cho một giai đoạn giao thoa văn hóa đặc sắc trong lịch sử Việt Nam.', ''),
(UUID(), '6addf272c5656cda07dfc243', 'zh', NULL, '您现在参观的是启定陵，又称应陵，这是阮朝陵墓系统中最独特且最具争议的建筑作品。启定陵是大胆融合东西方、欧亚建筑风格的产物，反映了这位皇帝追求新奇的个性。尽管面积最小，但它却是耗时最长、耗费人力和财力最多的陵墓。最璀璨的亮点位于天定宫内，那里有精美绝伦、细节繁复的瓷器和玻璃拼贴浮雕。启定陵犹如一座傲立在周字山坡上的雄伟城堡，是越南历史上一段特殊文化交融时期的有力见证。', ''),
(UUID(), '6addf28cc5656cda07dfc244', 'en', NULL, 'Welcome to the Tomb of Minh Mang, also known as Hieu Lang. This site is widely regarded as having the most majestic, imposing, and standard architecture of the Nguyen Dynasty mausoleums. Encompassed within a vast natural landscape, Minh Mang''s Tomb embodies Confucian ideals with a perfectly symmetrical central spirit path. The complex consists of nearly 40 large and small structures arranged in strict, sequential order, from the Great Red Gate, the courtyard, and the stele pavilion, to the temples and the emperor''s burial mound. The exquisite combination of grand architectural art with the scenery of lakes and shaded pine hills creates a dignified, solemn, yet poetic beauty, accurately reflecting the stature of a wise and strategic emperor.', ''),
(UUID(), '6addf28cc5656cda07dfc244', 'ja', NULL, 'ミンマン帝陵、別名ヒエウラン（孝陵）へようこそ。この場所は、グエン朝の陵墓の中で最も荘厳で堂々としており、標準的な建築であると高く評価されています。広大な自然景観に包まれたミンマン帝陵は、完璧な対称性を持つ中央の神道によって儒教の理想を体現しています。この複合施設は、大紅門（ダイホンモン）、中庭、碑亭から、霊廟や皇帝の墳丘に至るまで、厳格で順序立った配置の40近くの大小の建造物から構成されています。壮大な建築芸術と湖や木陰の松の丘の風景との絶妙な組み合わせは、威厳があり厳粛でありながらも詩的な美しさを生み出し、賢明で戦略的であった皇帝の威光を正確に反映しています。', ''),
(UUID(), '6addf28cc5656cda07dfc244', 'ko', NULL, '민망 황릉, 일명 히에우랑(Hieu Lang)에 오신 것을 환영합니다. 이곳은 응우옌 왕조의 능 중에서 가장 장엄하고 위풍당당하며 표준적인 건축 양식을 지닌 것으로 평가받고 있습니다. 광활한 자연 경관 속에 자리 잡은 민망 황릉은 완벽한 대칭을 이루는 중앙 신도를 통해 유교적 이상을 구체화합니다. 이 단지는 대홍문(Great Red Gate), 마당, 비각에서부터 사당과 황제의 무덤에 이르기까지 엄격하고 순차적인 순서로 배열된 40여 개의 크고 작은 구조물로 구성되어 있습니다. 웅장한 건축 예술과 호수, 그늘진 소나무 언덕의 풍경이 절묘하게 조화를 이루어 위엄 있고 엄숙하면서도 시적인 아름다움을 자아내며, 현명하고 전략적이었던 황제의 위상을 정확하게 반영합니다.', ''),
(UUID(), '6addf28cc5656cda07dfc244', 'vi', NULL, 'Chào mừng bạn đến với lăng Minh Mạng, hay Hiếu Lăng. Nơi đây được đánh giá là lăng tẩm có kiến trúc uy nghiêm, bề thế và chuẩn mực nhất của triều Nguyễn. Nằm trọn trong một không gian thiên nhiên rộng lớn, lăng Minh Mạng mang đậm tư tưởng Nho giáo với trục thần đạo trung tâm đối xứng hoàn hảo. Quần thể gồm gần 40 công trình lớn nhỏ được bố trí lớp lang, chặt chẽ, từ Đại Hồng Môn, sân chầu, nhà bia, cho đến điện thờ và phần mộ của nhà vua. Sự kết hợp tinh tế giữa nghệ thuật kiến trúc hoành tráng và cảnh quan hồ nước, đồi thông rợp bóng mát đã tạo nên một vẻ đẹp đường bệ, trang nghiêm nhưng không kém phần thơ mộng, phản ánh đúng tầm vóc của một vị vua anh minh và tài lược.', ''),
(UUID(), '6addf28cc5656cda07dfc244', 'zh', NULL, '欢迎来到明命陵，又称孝陵。这里被认为是阮朝陵墓中建筑最庄严、宏伟且最规范的。明命陵坐落在一片广阔的自然空间中，沿着一条完美对称的中央神道展开，深受儒家思想的影响。整个建筑群由近40座大小不一的建筑组成，布局严谨有序，从大红门、朝廷、碑亭，一直延伸到祭祀殿堂和皇帝的陵墓。宏大的建筑艺术与湖泊、松林成荫的自然景观巧妙结合，营造出一种端庄、肃穆又不失诗意的古典美，准确地反映了这位英明且富有谋略的皇帝的风范。', ''),
(UUID(), '6addf298c5656cda07dfc245', 'en', NULL, 'Welcome to the Tomb of Gia Long, or Thien Tho Lang, the resting place of the founding emperor of the Nguyen Dynasty. Located far from the city center, Gia Long''s Tomb lies quietly nestled amidst a majestic and pristine mountainous landscape. The most unique feature of this mausoleum is its open design; it has no enclosing walls, utilizing the rolling mountains themselves as a natural screen. The architecture is simple and rustic yet exudes the majesty and grandeur of a founding monarch. The picturesque feng shui landscape and the absolute tranquility, accompanied by the sound of wind whispering through the pines, create a sacred atmosphere, transporting visitors back to the earliest pages of Nguyen Dynasty history.', ''),
(UUID(), '6addf298c5656cda07dfc245', 'ja', NULL, 'グエン朝の初代皇帝が眠る場所、ザーロン帝陵（天授陵）へようこそ。市内中心部から遠く離れたザーロン帝陵は、雄大で手つかずの自然が残る山々の風景の中に静かに佇んでいます。この陵墓の最大の特徴はそのオープンな設計です。周囲を囲む壁が一切なく、うねる山々そのものを自然の屏風として利用しています。建築はシンプルで素朴ですが、建国の君主としての威厳と壮大さを放っています。絵画のように美しい風水の景観と、松林を吹き抜ける風の音に伴う絶対的な静寂は神聖な雰囲気を醸し出し、訪れる人々をグエン朝の歴史の最初のページへと誘います。', ''),
(UUID(), '6addf298c5656cda07dfc245', 'ko', NULL, '응우옌 왕조의 초대 황제가 잠든 곳, 쟈롱 황릉(티엔토랑)에 오신 것을 환영합니다. 도심에서 멀리 떨어진 쟈롱 황릉은 웅장하고 훼손되지 않은 산악 지대 한가운데 조용히 자리 잡고 있습니다. 이 능의 가장 독특한 특징은 개방형 디자인으로, 능을 둘러싼 담장이 없으며 굽이치는 산맥 그 자체를 천연 병풍으로 사용한다는 점입니다. 건축 양식은 단순하고 소박하지만 건국 군주의 위엄과 장엄함을 발산합니다. 그림 같은 풍수지리적 경관과 소나무 사이로 불어오는 바람 소리가 더해진 절대적인 고요함은 신성한 분위기를 자아내며, 방문객들을 응우옌 왕조 역사의 첫 페이지로 안내합니다.', ''),
(UUID(), '6addf298c5656cda07dfc245', 'vi', NULL, 'Chào mừng bạn đến với lăng Gia Long, hay Thiên Thọ Lăng, nơi an nghỉ của vị vua sáng lập ra triều đại nhà Nguyễn. Nằm cách xa trung tâm thành phố, lăng Gia Long ẩn mình tĩnh lặng giữa một quần thể núi non hùng vĩ và hoang sơ. Điểm đặc biệt nhất của lăng tẩm này là thiết kế mở, hoàn toàn không có la thành bao bọc, lấy chính những dãy núi nhấp nhô làm bức bình phong tự nhiên. Kiến trúc của lăng đơn giản, mộc mạc nhưng toát lên vẻ uy nghi, bề thế của một vị vua khai quốc. Bức tranh phong thủy hữu tình, không gian tĩnh lặng tuyệt đối hòa cùng tiếng thông reo trong gió tạo nên một cảm giác thiêng liêng, đưa du khách trở về với những trang sử đầu tiên của triều Nguyễn.', ''),
(UUID(), '6addf298c5656cda07dfc245', 'zh', NULL, '欢迎来到嘉隆陵，又称天授陵，这是阮朝开国皇帝的安息之地。嘉隆陵远离市中心，静静地隐藏在一片雄伟而原始的群山之中。这座陵墓最大的特色是其开放式的设计，完全没有围墙环绕，而是以起伏的山脉作为天然的屏风。其建筑风格简单质朴，却散发着开国君主的威严与宏大。风景如画的风水布局、绝对宁静的空间以及风穿过松林的沙沙声，营造出一种神圣的氛围，带领游客回到阮朝历史的最初篇章。', ''),
(UUID(), '6addf2a5c5656cda07dfc246', 'en', NULL, 'You are standing at the Nam Giao Esplanade, an immensely important spiritual architectural site of the Nguyen Dynasty. This is the only relatively intact altar of its kind preserved in Vietnam, where the Nguyen emperors personally presided over spring sacrifices to Heaven and Earth, praying for favorable weather, national peace, and prosperity. The Nam Giao Esplanade is designed with three south-facing terraces, symbolizing Heaven (round), Earth (square), and Humanity. Standing amidst this vast space, surrounded by a dense forest of ancient pines, you will feel the sacred connection between humanity and the universe, gaining a deeper understanding of royal beliefs and the ancient aspirations for peace and prosperity.', ''),
(UUID(), '6addf2a5c5656cda07dfc246', 'ja', NULL, 'あなたは今、グエン朝の非常に重要な精神的建築物であるナムザオ祭壇（南郊壇）に立っています。ここはベトナムで比較的無傷で保存されている唯一の祭壇であり、グエン朝の皇帝たちが春に自ら天地を祀る儀式を主宰し、天候の順調、国家の平和、そして繁栄を祈願した場所です。ナムザオ祭壇は南向きの3層のテラスで設計されており、それぞれ天（円形）、地（方形）、そして人を象徴しています。鬱蒼とした古い松林に囲まれたこの広大な空間の中心に立つと、人類と宇宙との間の神聖なつながりを感じ、宮廷の信仰や、平和と繁栄に対する古人の切なる願いをより深く理解することができるでしょう。', ''),
(UUID(), '6addf2a5c5656cda07dfc246', 'ko', NULL, '여러분은 지금 응우옌 왕조의 매우 중요한 영적 건축물인 남자오 단(Nam Giao Esplanade)에 서 계십니다. 이곳은 베트남에 비교적 온전하게 보존되어 있는 유일한 제단으로, 응우옌 왕조의 황제들이 봄마다 직접 하늘과 땅에 제사를 지내며 순조로운 날씨와 국가의 평안, 번영을 기원하던 곳입니다. 남자오 단은 남쪽을 향한 3층의 테라스로 설계되었으며, 각각 하늘(원형), 땅(사각형), 그리고 인간을 상징합니다. 울창한 고송림으로 둘러싸인 이 광활한 공간 한가운데 서 있으면 인간과 우주 사이의 신성한 연결고리를 느낄 수 있으며, 황실의 신앙과 평화 및 번영을 향한 옛사람들의 열망을 더 깊이 이해할 수 있습니다.', ''),
(UUID(), '6addf2a5c5656cda07dfc246', 'vi', NULL, 'Bạn đang đứng tại Đàn Nam Giao, một công trình kiến trúc tâm linh vô cùng quan trọng của triều Nguyễn. Nơi đây là đàn tế duy nhất còn được bảo tồn khá nguyên vẹn ở Việt Nam, nơi các vị vua triều Nguyễn đích thân tổ chức lễ tế trời đất vào mùa xuân để cầu mưa thuận gió hòa, quốc thái dân an. Đàn Nam Giao được thiết kế gồm ba tầng sân hướng về phía Nam, tượng trưng cho Thiên (Trời - hình tròn), Địa (Đất - hình vuông) và Nhân (Người). Đứng giữa không gian rộng lớn, bao quanh bởi rừng thông cổ thụ bạt ngàn, bạn sẽ cảm nhận được sự kết nối linh thiêng giữa con người và vũ trụ, và hiểu thêm về tín ngưỡng cung đình cũng như khát vọng hòa bình, thịnh vượng của người xưa.', ''),
(UUID(), '6addf2a5c5656cda07dfc246', 'zh', NULL, '您现在站在南郊坛，这是阮朝极为重要的精神建筑。这是越南唯一保存相对完整的祭坛，阮朝历代皇帝在春季会亲自在此举行祭天祀地的仪式，祈求风调雨顺、国泰民安。南郊坛设计为朝南的三层平台，分别象征着天（圆形）、地（方形）和人。站在被苍翠古松林环绕的广阔空间中，您会感受到人类与宇宙之间神圣的连接，并更深入地了解宫廷的信仰以及古人对和平与繁荣的渴望。', ''),
(UUID(), '6adf5ff52219d18ee88b3d4d', 'en', NULL, 'Welcome to Tu Hieu Pagoda, one of the most unique and historically significant ancient pagodas in the ancient capital of Hue. Hidden amidst a lush pine forest and the murmuring of a stream, Tu Hieu Pagoda is famous not only for its tranquil atmosphere but also for the touching story of Zen Master Nhat Dinh''s filial piety towards his elderly mother. Notably, this is also the resting place of the Nguyen Dynasty''s eunuchs, who contributed to building the pagoda to have a place of worship in their final years. With its harmonious architecture blending traditional temple design and pristine nature, Tu Hieu Pagoda offers visitors a profound sense of peace. It is also where the renowned Zen Master Thich Nhat Hanh spent his final years.', ''),
(UUID(), '6adf5ff52219d18ee88b3d4d', 'ja', NULL, 'フエの古都で最もユニークで歴史的に重要な古刹の一つ、トゥヒエウ寺（慈孝寺）へようこそ。青々とした松林とせせらぎの間にひっそりと佇むトゥヒエウ寺は、その静寂な雰囲気だけでなく、ニャット・ディン（一禅）禅師の老母に対する親孝行の感動的な物語でも有名です。特に、ここはグエン朝の宦官たちの安息の地でもあり、彼らは晩年の供養の場を確保するためにこの寺院の建設に貢献しました。伝統的な寺院建築と手つかずの自然が調和したトゥヒエウ寺は、訪れる人々に深い平安をもたらします。また、世界的な精神的指導者であるティック・ナット・ハン（釈一行）禅師が晩年を過ごした場所でもあります。', ''),
(UUID(), '6adf5ff52219d18ee88b3d4d', 'ko', NULL, '고도 유에(Hue)에서 가장 독특하고 역사적으로 중요한 고찰 중 하나인 뜨히에우(Tu Hieu) 사원에 오신 것을 환영합니다. 울창한 소나무 숲과 졸졸 흐르는 시냇물 사이에 숨겨진 뜨히에우 사원은 평온한 분위기뿐만 아니라 노모를 향한 녓딘(Nhat Dinh) 선사의 감동적인 효심 이야기로도 유명합니다. 특히 이곳은 노후에 의지할 곳을 마련하기 위해 사원 건축에 기여했던 응우옌 왕조 환관들의 안식처이기도 합니다. 전통 사찰 건축과 깨끗한 자연이 조화롭게 어우러진 뜨히에우 사원은 방문객들에게 깊은 평화로움을 선사하며, 세계적인 영적 지도자 틱낫한(Thich Nhat Hanh) 스님이 말년을 보낸 곳이기도 합니다.', ''),
(UUID(), '6adf5ff52219d18ee88b3d4d', 'vi', NULL, 'Chào mừng bạn đến với chùa Từ Hiếu, một trong những ngôi cổ tự độc đáo và mang đậm dấu ấn lịch sử nhất tại cố đô Huế. Ẩn mình giữa rừng thông xanh mát và tiếng suối róc rách, chùa Từ Hiếu không chỉ nổi tiếng bởi không gian thanh tịnh, mà còn bởi câu chuyện cảm động về lòng hiếu thảo của Thiền sư Nhất Định đối với mẹ già. Đặc biệt, đây còn là nơi an nghỉ của các vị thái giám triều Nguyễn – những người đã đóng góp xây dựng nên ngôi chùa để có nơi hương khói lúc cuối đời. Với kiến trúc hài hòa giữa đình chùa truyền thống và thiên nhiên hoang sơ, chùa Từ Hiếu mang đến cho du khách một cảm giác bình yên, sâu lắng, và là nơi thiền sư Thích Nhất Hạnh đã gắn bó trong những năm tháng cuối đời.', ''),
(UUID(), '6adf5ff52219d18ee88b3d4d', 'zh', NULL, '欢迎来到慈孝寺，这是顺化古都最独特、最具历史印记的古刹之一。慈孝寺掩映在葱郁的松林和潺潺的溪流中，不仅以其宁静的氛围而闻名，更因一禅师对其老母亲感人至深的孝道故事而得名。特别的是，这里也是阮朝太监们的安息之地，他们捐资修建了这座寺庙，以便在晚年能有香火供奉。慈孝寺将传统寺庙建筑与原始自然完美融合，给游客带来一种深沉的宁静感。这里也是著名的释一行禅师度过晚年时光的地方。', '');